CREATE TABLE IF NOT EXISTS playbooks (id serial PRIMARY KEY, slug text NOT NULL UNIQUE, title text NOT NULL, description text, phase text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS playbook_steps (id serial PRIMARY KEY, playbook_id integer NOT NULL REFERENCES playbooks(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, sort_order integer NOT NULL DEFAULT 0, checklist jsonb NOT NULL DEFAULT '[]', created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
